insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-20','en-c1-20',null,5,20,'published',1,'{"id":"en-c1-20","baseId":"en-c1-20","revision":1,"level":"C1","levelIndex":5,"order":20,"title":"Academic essay: dalil va counterargument","objective":"Talabchan essayda pozitsiyani kvalifikatsiya va manba bilan rivojlantirasiz.","context":"Academic essay: dalil va counterargument","prerequisites":["en-c1-19"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil.","Counterargument eng kuchli shaklda, response uning asosli qismiga javob.","Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi."],"pattern":"qualified thesis → evidence → counterargument → response","examples":["A mixed approach is preferable under the current constraints.","The evidence supports access rather than a universal benefit.","A reasonable objection concerns staffing.","That objection limits the scale, not the value, of a trial.","The conclusion remains conditional on the review results.","No source establishes a permanent solution."],"vocabulary":[{"id":"en-c1-20-v0","term":"thesis","meaning":"asosiy pozitsiya","ipa":"/ˈθiːsɪs/","collocation":"a qualified thesis","example":"The thesis becomes more qualified but more defensible."},{"id":"en-c1-20-v1","term":"rebuttal","meaning":"qarshi javob","ipa":"/rɪˈbʌtəl/","collocation":"a reasoned rebuttal","example":"a reasoned rebuttal"},{"id":"en-c1-20-v2","term":"nuance","meaning":"nozik farq","ipa":"/ˈnjuːɑːns/","collocation":"preserve nuance","example":"preserve nuance"},{"id":"en-c1-20-v3","term":"substantiation","meaning":"dalillash","ipa":"/səbˌstænʃiˈeɪʃən/","collocation":"seek substantiation","example":"seek substantiation"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["qualified thesis → evidence → counterargument → response","A mixed approach is preferable under the current constraints.","The evidence supports access rather than a universal benefit."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Evidence supports mixed access needs.","Staffing restricts the feasible options.","Recommend a bounded trial with explicit conditions."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"That objection limits the scale, not the value, of a trial.","audio":"/english-course/v7.23/en-c1-20-dictation.mp3"},"exercises":[{"id":"en-c1-20-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The thesis remains conditional ___ the results.","answers":["on"],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response","options":["on","to","of"]},{"id":"en-c1-20-gap","type":"grammarFill","skill":"grammar","prompt":"The thesis remains conditional ___ the results.","answers":["on"],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response"},{"id":"en-c1-20-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["A mixed approach is preferable under the current constraints."],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response","tokens":["A","mixed","approach","is","preferable","under","the","current","constraints."]},{"id":"en-c1-20-fix","type":"correction","skill":"grammar","prompt":"Staffing concerns are only resistance to change.","answers":["Staffing concerns are a relevant constraint on the trial."],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response"},{"id":"en-c1-20-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["asosiy pozitsiya","qarshi javob","nozik farq","dalillash"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"qualified thesis → evidence → counterargument → response","left":["thesis","rebuttal","nuance","substantiation"],"options":["asosiy pozitsiya","qarshi javob","nozik farq","dalillash"]},{"id":"en-c1-20-transform","type":"transformation","skill":"grammar","prompt":"Qualified thesis: A mixed approach is always best.","answers":["A mixed approach is preferable under the current constraints."],"hint":"qualified thesis → evidence → counterargument → response","explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil."},{"id":"en-c1-20-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Evidence supports mixed access needs.","Staffing restricts the feasible options.","Recommend a bounded trial with explicit conditions."],"answers":["Evidence supports mixed access needs.\nStaffing restricts the feasible options.\nRecommend a bounded trial with explicit conditions."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-20-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["A mixed approach is preferable under the current constraints."],"tokens":["A","mixed","approach","is","preferable","under","the","current","constraints."],"hint":"qualified thesis → evidence → counterargument → response","explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil."},{"id":"en-c1-20-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Paraphrasing: ma’no chegarasi: Til vositasini tanlang: The programme may ___ to confidence. (contribute)","answers":["contribute"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset","options":["contribute","contributes","contributed"],"recap":true,"sourceLesson":"Paraphrasing: ma’no chegarasi"},{"id":"en-c1-20-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Summarising va synthesis: Til vositasini tanlang: Taken ___, they suggest a mixed approach.","answers":["together"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …","options":["together","combines","combining"],"recap":true,"sourceLesson":"Summarising va synthesis"},{"id":"en-c1-20-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Argument evaluation: premise va xulosa: Til vositasini tanlang: A popular programme is not necessarily ___.","answers":["effective"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test","options":["effective","effectiveness","effectively"],"recap":true,"sourceLesson":"Argument evaluation: premise va xulosa"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"An essay recommends a mixed schedule because the survey and interviews reveal different access needs. Its strongest counterargument concerns staffing: alternating days may make reliable supervision harder. The first draft dismisses this concern as resistance to change. The revision acknowledges the real constraint and limits the trial to days when staff are available. The thesis becomes more qualified but more defensible. An academic argument should be able to explain why its recommendation survives a serious objection and where it must change. Qualification is not indecision. It defines the conditions under which the position is supported. The final paragraph therefore recommends a bounded trial and a review, rather than claiming that a permanent solution has been proven.","sentences":["An essay recommends a mixed schedule because the survey and interviews reveal different access needs.","Its strongest counterargument concerns staffing: alternating days may make reliable supervision harder.","The first draft dismisses this concern as resistance to change.","The revision acknowledges the real constraint and limits the trial to days when staff are available.","The thesis becomes more qualified but more defensible.","An academic argument should be able to explain why its recommendation survives a serious objection and where it must change.","Qualification is not indecision.","It defines the conditions under which the position is supported.","The final paragraph therefore recommends a bounded trial and a review, rather than claiming that a permanent solution has been proven."],"questions":[{"id":"en-c1-20-reading0","type":"choice","skill":"reading","prompt":"Eng kuchli counterargument?","answers":["reliable staffing"],"explanation":"Supervision constraint.","hint":"qualified thesis → evidence → counterargument → response","options":["reliable staffing","hatred of change","no access needs"]},{"id":"en-c1-20-reading1","type":"choice","skill":"reading","prompt":"Qualification nima qiladi?","answers":["defines support conditions"],"explanation":"Shartlarini aniqlaydi.","hint":"qualified thesis → evidence → counterargument → response","options":["defines support conditions","removes every position","proves permanent success"]},{"id":"en-c1-20-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"qualified thesis → evidence → counterargument → response","options":["An essay recommends a mixed schedule because the survey and interviews reveal different access needs.","Its strongest counterargument concerns staffing: alternating days may make reliable supervision harder.","The first draft dismisses this concern as resistance to change.","The revision acknowledges the real constraint and limits the trial to days when staff are available.","The thesis becomes more qualified but more defensible.","An academic argument should be able to explain why its recommendation survives a serious objection and where it must change.","Qualification is not indecision.","It defines the conditions under which the position is supported.","The final paragraph therefore recommends a bounded trial and a review, rather than claiming that a permanent solution has been proven."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is thesis. An essay recommends a mixed schedule because the survey and interviews reveal different access needs. Its strongest counterargument concerns staffing: alternating days may make reliable supervision harder. Speaker two: My main point is qualification. A defensible position states the conditions under which it holds. An essay recommends a mixed schedule because the survey and interviews reveal different access needs. Its strongest counterargument concerns staffing: alternating days may make reliable supervision harder. The first draft dismisses this concern as resistance to change. The revision acknowledges the real constraint and limits the trial to days when staff are available. The thesis becomes more qualified but more defensible. An academic argument should be able to explain why its recommendation survives a serious objection and where it must change. Qualification is not indecision. It defines the conditions under which the position is supported. The final paragraph therefore recommends a bounded trial and a review, rather than claiming that a permanent solution has been proven.","audio":"/english-course/v7.23/en-c1-20.mp3","synthetic":true,"questions":[{"id":"en-c1-20-listening0","type":"choice","skill":"listening","prompt":"Eng kuchli counterargument?","answers":["reliable staffing"],"explanation":"Supervision constraint.","hint":"qualified thesis → evidence → counterargument → response","options":["reliable staffing","hatred of change","no access needs"]},{"id":"en-c1-20-listening1","type":"choice","skill":"listening","prompt":"Qualification nima qiladi?","answers":["defines support conditions"],"explanation":"Shartlarini aniqlaydi.","hint":"qualified thesis → evidence → counterargument → response","options":["defines support conditions","removes every position","proves permanent success"]},{"id":"en-c1-20-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["thesis","qualification"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"qualified thesis → evidence → counterargument → response","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-20-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["That objection limits the scale, not the value, of a trial."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"qualified thesis → evidence → counterargument → response","audio":"/english-course/v7.23/en-c1-20-dictation.mp3","transcript":"That objection limits the scale, not the value, of a trial."}]},"writing":{"task":"Argumentative essay: qualified thesis, ikki manba, serious counterargument va bounded conclusion.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"A mixed schedule is preferable under the current constraints because the survey and interviews reveal different access needs. However, the staffing objection is substantial: alternating days may reduce reliable supervision. That concern limits the scale of the trial rather than making access irrelevant. I propose using only days with confirmed staff and reviewing participation after two weeks. The evidence does not establish a permanent solution, but it supports a bounded experiment. A qualified thesis makes the conditions of support visible and explains how the recommendation responds to a serious counterargument.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["A mixed approach is preferable under the current constraints.","The evidence supports access rather than a universal benefit.","A reasonable objection concerns staffing."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Argumentative essay: qualified thesis, ikki manba, serious counterargument va bounded conclusion. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Argumentative essay: qualified thesis, ikki manba, serious counterargument va bounded conclusion.","exit":[[{"id":"en-c1-20-exit0","type":"grammarFill","skill":"grammar","prompt":"The thesis remains conditional ___ the results.","answers":["on"],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response"},{"id":"en-c1-20-exit1","type":"grammarFill","skill":"grammar","prompt":"An objection ___ staffing. (concern)","answers":["concerns"],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response"},{"id":"en-c1-20-exit2","type":"grammarFill","skill":"grammar","prompt":"No source ___ a permanent solution. (establish)","answers":["establishes"],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response"},{"id":"en-c1-20-exit3","type":"choice","skill":"grammar","prompt":"Eng kuchli counterargument?","answers":["reliable staffing"],"explanation":"Supervision constraint.","hint":"qualified thesis → evidence → counterargument → response","options":["reliable staffing","hatred of change","no access needs"]},{"id":"en-c1-20-exit4","type":"choice","skill":"grammar","prompt":"Qualification nima qiladi?","answers":["defines support conditions"],"explanation":"Shartlarini aniqlaydi.","hint":"qualified thesis → evidence → counterargument → response","options":["defines support conditions","removes every position","proves permanent success"]}],[{"id":"en-c1-20-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The evidence supports access rather than a universal benefit."],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response","tokens":["The","evidence","supports","access","rather","than","a","universal","benefit."]},{"id":"en-c1-20-exit-b1","type":"grammarFill","skill":"grammar","prompt":"An objection ___ staffing. (concern)","answers":["concerns"],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response"},{"id":"en-c1-20-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["That objection limits the scale, not the value, of a trial."],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response","tokens":["That","objection","limits","the","scale,","not","the","value,","of","a","trial."]},{"id":"en-c1-20-exit-b3","type":"choice","skill":"grammar","prompt":"Eng kuchli counterargument?","answers":["reliable staffing"],"explanation":"Supervision constraint.","hint":"qualified thesis → evidence → counterargument → response","options":["reliable staffing","hatred of change","no access needs"]},{"id":"en-c1-20-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["No source establishes a permanent solution."],"explanation":"Thesis aniq va bahslanuvchi; har paragraph alohida sabab va dalil. Counterargument eng kuchli shaklda, response uning asosli qismiga javob. Synthesis conclusion yangi dalil kiritmasdan oldingi reasoningni yakunlaydi.","hint":"qualified thesis → evidence → counterargument → response","tokens":["No","source","establishes","a","permanent","solution."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-20","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-c1-20-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Paraphrasing: ma’no chegarasi: Til vositasini tanlang: The programme may ___ to confidence. (contribute)","answers":["contribute"],"explanation":"Paraphrase mazmun, scope, attribution va certaintyni saqlaydi. Synonym almashtirishning o‘zi yetmaydi; structure o‘zgarishi mumkin, claim emas. May contribute to → causes ga o‘tish noto‘g‘ri kuchaytirish; source reference qoladi.","hint":"may contribute → could play a part / some → a subset","options":["contribute","contributes","contributed"],"recap":true,"sourceLesson":"Paraphrasing: ma’no chegarasi"},{"id":"en-c1-20-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Summarising va synthesis: Til vositasini tanlang: Taken ___, they suggest a mixed approach.","answers":["together"],"explanation":"Summary bitta manbaning asosiy mazmuni; synthesis manbalar o‘rtasidagi aloqani tuzadi. Turli population va method natijalari yuzaki qarama-qarshi ko‘rinishi mumkin. Har claimni manbasiga bog‘lang, mos kelmagan qismni yashirmang.","hint":"Source A … whereas Source B … / taken together …","options":["together","combines","combining"],"recap":true,"sourceLesson":"Summarising va synthesis"},{"id":"en-c1-20-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Argument evaluation: premise va xulosa: Til vositasini tanlang: A popular programme is not necessarily ___.","answers":["effective"],"explanation":"Valid inference premise bilan conclusion aloqasini, evidence esa premise rostligini tekshiradi. Popularity effectivenessga, correlation causationga avtomatik dalil emas. Counterexample qamrovni tekshiradi; qarshi fikrni xolis kuchli shaklda bayon qiling.","hint":"premise → inference → conclusion / assumption → test","options":["effective","effectiveness","effectively"],"recap":true,"sourceLesson":"Argument evaluation: premise va xulosa"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-21','en-c1-21',null,5,21,'published',1,'{"id":"en-c1-21","baseId":"en-c1-21","revision":1,"level":"C1","levelIndex":5,"order":21,"title":"Proposal: ehtiyoj, resurs va baholash","objective":"Amalga oshadigan proposalni maqsad va success criterialari bilan tuzasiz.","context":"Proposal: ehtiyoj, resurs va baholash","prerequisites":["en-c1-20"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi.","Success criterion faqat ish bajarilishi emas, maqsadga mos natija.","Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang."],"pattern":"need → action → resources → risk → evaluation","examples":["The proposal addresses unequal access.","Implementation would begin with a limited trial.","The organiser would coordinate staffing.","Success would be assessed against participation criteria.","Should staffing fall short, the original schedule would remain.","The proposal does not guarantee a long-term effect."],"vocabulary":[{"id":"en-c1-21-v0","term":"objective","meaning":"maqsad","ipa":"/əbˈdʒektɪv/","collocation":"a measurable objective","example":"a measurable objective"},{"id":"en-c1-21-v1","term":"resource","meaning":"resurs","ipa":"/rɪˈsɔːs/","collocation":"allocate resources","example":"allocate resources"},{"id":"en-c1-21-v2","term":"mitigation","meaning":"xavfni kamaytirish","ipa":"/ˌmɪtɪˈɡeɪʃən/","collocation":"risk mitigation","example":"risk mitigation"},{"id":"en-c1-21-v3","term":"milestone","meaning":"bosqich natijasi","ipa":"/ˈmaɪlstəʊn/","collocation":"a review milestone","example":"a review milestone"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["need → action → resources → risk → evaluation","The proposal addresses unequal access.","Implementation would begin with a limited trial."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["A barrier has been identified.","A trial action and coordinator are specified.","Judge success using evidence aligned with the need."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Success would be assessed against participation criteria.","audio":"/english-course/v7.23/en-c1-21-dictation.mp3"},"exercises":[{"id":"en-c1-21-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Success would be assessed ___ criteria.","answers":["against"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation","options":["against","onto","at"]},{"id":"en-c1-21-gap","type":"grammarFill","skill":"grammar","prompt":"Success would be assessed ___ criteria.","answers":["against"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation"},{"id":"en-c1-21-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The proposal addresses unequal access."],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation","tokens":["The","proposal","addresses","unequal","access."]},{"id":"en-c1-21-fix","type":"correction","skill":"grammar","prompt":"We delivered one session, so access definitely improved.","answers":["We delivered one session; improved access requires participation evidence."],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation"},{"id":"en-c1-21-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["maqsad","resurs","xavfni kamaytirish","bosqich natijasi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"need → action → resources → risk → evaluation","left":["objective","resource","mitigation","milestone"],"options":["maqsad","resurs","xavfni kamaytirish","bosqich natijasi"]},{"id":"en-c1-21-transform","type":"transformation","skill":"grammar","prompt":"Contingency bilan: If staffing falls short, the original schedule will remain.","answers":["Should staffing fall short, the original schedule will remain."],"hint":"need → action → resources → risk → evaluation","explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi."},{"id":"en-c1-21-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["A barrier has been identified.","A trial action and coordinator are specified.","Judge success using evidence aligned with the need."],"answers":["A barrier has been identified.\nA trial action and coordinator are specified.\nJudge success using evidence aligned with the need."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-21-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["objective","resource","mitigation","milestone"],"options":["a measurable objective","allocate resources","risk mitigation","a review milestone"],"answers":["a measurable objective","allocate resources","risk mitigation","a review milestone"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A proposal promises to improve access by adding one session. It lists the activity but gives no way to judge whether access improves. The editor asks the team to identify which students currently face barriers and how their participation will be recorded. The proposal then names a coordinator, specifies existing staffing, and includes a contingency if supervision is unavailable. The trial’s success criterion compares participation among the relevant groups rather than counting sessions delivered. This does not require an elaborate prediction model. It requires alignment between the need, the action, and the evidence used to evaluate it. A proposal can be ambitious while remaining honest about what a short trial can demonstrate.","sentences":["A proposal promises to improve access by adding one session.","It lists the activity but gives no way to judge whether access improves.","The editor asks the team to identify which students currently face barriers and how their participation will be recorded.","The proposal then names a coordinator, specifies existing staffing, and includes a contingency if supervision is unavailable.","The trial’s success criterion compares participation among the relevant groups rather than counting sessions delivered.","This does not require an elaborate prediction model.","It requires alignment between the need, the action, and the evidence used to evaluate it.","A proposal can be ambitious while remaining honest about what a short trial can demonstrate."],"questions":[{"id":"en-c1-21-reading0","type":"choice","skill":"reading","prompt":"Activity bilan success farqi?","answers":["a delivered session is not proof of improved access"],"explanation":"Maqsadga mos natija kerak.","hint":"need → action → resources → risk → evaluation","options":["a delivered session is not proof of improved access","they are always identical","success needs no criteria"]},{"id":"en-c1-21-reading1","type":"choice","skill":"reading","prompt":"Relevant groups nega?","answers":["the need concerns their barriers"],"explanation":"Need bilan evaluation alignment.","hint":"need → action → resources → risk → evaluation","options":["the need concerns their barriers","all groups are identical","only total sessions matter"]},{"id":"en-c1-21-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"need → action → resources → risk → evaluation","options":["A proposal promises to improve access by adding one session.","It lists the activity but gives no way to judge whether access improves.","The editor asks the team to identify which students currently face barriers and how their participation will be recorded.","The proposal then names a coordinator, specifies existing staffing, and includes a contingency if supervision is unavailable.","The trial’s success criterion compares participation among the relevant groups rather than counting sessions delivered.","This does not require an elaborate prediction model.","It requires alignment between the need, the action, and the evidence used to evaluate it.","A proposal can be ambitious while remaining honest about what a short trial can demonstrate."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is objective. A proposal promises to improve access by adding one session. It lists the activity but gives no way to judge whether access improves. Speaker two: My main point is evaluation. Evaluate the stated need rather than only counting completed activities. A proposal promises to improve access by adding one session. It lists the activity but gives no way to judge whether access improves. The editor asks the team to identify which students currently face barriers and how their participation will be recorded. The proposal then names a coordinator, specifies existing staffing, and includes a contingency if supervision is unavailable. The trial’s success criterion compares participation among the relevant groups rather than counting sessions delivered. This does not require an elaborate prediction model. It requires alignment between the need, the action, and the evidence used to evaluate it. A proposal can be ambitious while remaining honest about what a short trial can demonstrate.","audio":"/english-course/v7.23/en-c1-21.mp3","synthetic":true,"questions":[{"id":"en-c1-21-listening0","type":"choice","skill":"listening","prompt":"Activity bilan success farqi?","answers":["a delivered session is not proof of improved access"],"explanation":"Maqsadga mos natija kerak.","hint":"need → action → resources → risk → evaluation","options":["a delivered session is not proof of improved access","they are always identical","success needs no criteria"]},{"id":"en-c1-21-listening1","type":"choice","skill":"listening","prompt":"Relevant groups nega?","answers":["the need concerns their barriers"],"explanation":"Need bilan evaluation alignment.","hint":"need → action → resources → risk → evaluation","options":["the need concerns their barriers","all groups are identical","only total sessions matter"]},{"id":"en-c1-21-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["objective","evaluation"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"need → action → resources → risk → evaluation","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-21-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Success would be assessed against participation criteria."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"need → action → resources → risk → evaluation","audio":"/english-course/v7.23/en-c1-21-dictation.mp3","transcript":"Success would be assessed against participation criteria."}]},"writing":{"task":"Proposal yozing: need, action, coordinator, resource, risk va goal-linked evaluation.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"We propose one additional session to test whether access improves for students who currently face timetable barriers. The organiser would coordinate existing staff and record participation by the relevant groups. Success would be assessed against that objective, not merely the number of sessions delivered. Should staffing fall short, the original schedule would remain. After two weeks, the committee would compare participation and interview a small group about remaining barriers. The proposal is ambitious enough to test a useful change while limiting its claims to what the trial can demonstrate.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The proposal addresses unequal access.","Implementation would begin with a limited trial.","The organiser would coordinate staffing."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Proposal yozing: need, action, coordinator, resource, risk va goal-linked evaluation. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Proposal yozing: need, action, coordinator, resource, risk va goal-linked evaluation.","exit":[[{"id":"en-c1-21-exit0","type":"grammarFill","skill":"grammar","prompt":"Success would be assessed ___ criteria.","answers":["against"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation"},{"id":"en-c1-21-exit1","type":"grammarFill","skill":"grammar","prompt":"The organiser would ___ staffing. (coordinate)","answers":["coordinate"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation"},{"id":"en-c1-21-exit2","type":"grammarFill","skill":"grammar","prompt":"Should staffing ___ short, retain the schedule. (fall)","answers":["fall"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation"},{"id":"en-c1-21-exit3","type":"choice","skill":"grammar","prompt":"Activity bilan success farqi?","answers":["a delivered session is not proof of improved access"],"explanation":"Maqsadga mos natija kerak.","hint":"need → action → resources → risk → evaluation","options":["a delivered session is not proof of improved access","they are always identical","success needs no criteria"]},{"id":"en-c1-21-exit4","type":"choice","skill":"grammar","prompt":"Relevant groups nega?","answers":["the need concerns their barriers"],"explanation":"Need bilan evaluation alignment.","hint":"need → action → resources → risk → evaluation","options":["the need concerns their barriers","all groups are identical","only total sessions matter"]}],[{"id":"en-c1-21-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Implementation would begin with a limited trial."],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation","tokens":["Implementation","would","begin","with","a","limited","trial."]},{"id":"en-c1-21-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The organiser would ___ staffing. (coordinate)","answers":["coordinate"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation"},{"id":"en-c1-21-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Success would be assessed against participation criteria."],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation","tokens":["Success","would","be","assessed","against","participation","criteria."]},{"id":"en-c1-21-exit-b3","type":"choice","skill":"grammar","prompt":"Activity bilan success farqi?","answers":["a delivered session is not proof of improved access"],"explanation":"Maqsadga mos natija kerak.","hint":"need → action → resources → risk → evaluation","options":["a delivered session is not proof of improved access","they are always identical","success needs no criteria"]},{"id":"en-c1-21-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The proposal does not guarantee a long-term effect."],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation","tokens":["The","proposal","does","not","guarantee","a","long-term","effect."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-21","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-22','en-c1-22',null,5,22,'published',1,'{"id":"en-c1-22","baseId":"en-c1-22","revision":1,"level":"C1","levelIndex":5,"order":22,"title":"Analytical report: pattern va limitation","objective":"Natijalarni tavsif, talqin va tavsiyaga aniq ajratasiz.","context":"Analytical report: pattern va limitation","prerequisites":["en-c1-21"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish.","Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang.","Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing."],"pattern":"finding → interpretation → limitation → recommendation","examples":["Attendance increased during the trial.","The increase was concentrated in one group.","The pattern may reflect the revised timetable.","The report cannot separate that effect from promotion.","A second trial should compare those factors.","The recommendation is provisional rather than permanent."],"vocabulary":[{"id":"en-c1-22-v0","term":"pattern","meaning":"qonuniyat","ipa":"/ˈpætən/","collocation":"identify a pattern","example":"The pattern may reflect the revised timetable."},{"id":"en-c1-22-v1","term":"confound","meaning":"aralash sabab","ipa":"/kənˈfaʊnd/","collocation":"a possible confound","example":"A report attributing the increase entirely to the timetable would ignore a possible confound."},{"id":"en-c1-22-v2","term":"provisional","meaning":"vaqtinchalik","ipa":"/prəˈvɪʒənəl/","collocation":"a provisional recommendation","example":"The recommendation is provisional rather than permanent."},{"id":"en-c1-22-v3","term":"disaggregate","meaning":"guruhlarga ajratmoq","ipa":"/ˌdɪsˈæɡrɪɡeɪt/","collocation":"disaggregate results","example":"She also disaggregates the total by the groups relevant to the access objective."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["finding → interpretation → limitation → recommendation","Attendance increased during the trial.","The increase was concentrated in one group."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Attendance increased unevenly.","Timetable and promotion changed together.","Disaggregate results and test competing explanations."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The report cannot separate that effect from promotion.","audio":"/english-course/v7.23/en-c1-22-dictation.mp3"},"exercises":[{"id":"en-c1-22-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The increase was ___ in one group. (concentrate)","answers":["concentrated"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation","options":["concentrated","concentrating","concentrate"]},{"id":"en-c1-22-gap","type":"grammarFill","skill":"grammar","prompt":"The increase was ___ in one group. (concentrate)","answers":["concentrated"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation"},{"id":"en-c1-22-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Attendance increased during the trial."],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation","tokens":["Attendance","increased","during","the","trial."]},{"id":"en-c1-22-fix","type":"correction","skill":"grammar","prompt":"The increase proves the timetable alone caused it.","answers":["The increase may reflect the timetable, but promotion changed at the same time."],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation"},{"id":"en-c1-22-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qonuniyat","aralash sabab","vaqtinchalik","guruhlarga ajratmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"finding → interpretation → limitation → recommendation","left":["pattern","confound","provisional","disaggregate"],"options":["qonuniyat","aralash sabab","vaqtinchalik","guruhlarga ajratmoq"]},{"id":"en-c1-22-transform","type":"transformation","skill":"grammar","prompt":"Limit qo‘shing: The timetable caused the increase.","answers":["The increase may reflect the timetable, but the effect of promotion is uncertain."],"hint":"finding → interpretation → limitation → recommendation","explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish."},{"id":"en-c1-22-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Attendance increased unevenly.","Timetable and promotion changed together.","Disaggregate results and test competing explanations."],"answers":["Attendance increased unevenly.\nTimetable and promotion changed together.\nDisaggregate results and test competing explanations."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Attendance increased during the trial, mainly among students already living near the school. The timetable changed at the same time as a promotional campaign. A report attributing the increase entirely to the timetable would ignore a possible confound. The writer separates the observed pattern from its interpretation and recommends another trial that records how participants heard about the sessions. She also disaggregates the total by the groups relevant to the access objective. The limitation appears beside the finding because it changes what can be inferred, rather than as a minor footnote. Analytical reporting is useful when it helps decision makers see both a pattern and the questions that pattern leaves unanswered.","sentences":["Attendance increased during the trial, mainly among students already living near the school.","The timetable changed at the same time as a promotional campaign.","A report attributing the increase entirely to the timetable would ignore a possible confound.","The writer separates the observed pattern from its interpretation and recommends another trial that records how participants heard about the sessions.","She also disaggregates the total by the groups relevant to the access objective.","The limitation appears beside the finding because it changes what can be inferred, rather than as a minor footnote.","Analytical reporting is useful when it helps decision makers see both a pattern and the questions that pattern leaves unanswered."],"questions":[{"id":"en-c1-22-reading0","type":"choice","skill":"reading","prompt":"Confound nima?","answers":["promotion changed at the same time"],"explanation":"Ikki o‘zgarish bir vaqtda.","hint":"finding → interpretation → limitation → recommendation","options":["promotion changed at the same time","attendance was never counted","all distant students came"]},{"id":"en-c1-22-reading1","type":"choice","skill":"reading","prompt":"Disaggregate nega?","answers":["total hides who gained access"],"explanation":"Group-specific aim.","hint":"finding → interpretation → limitation → recommendation","options":["total hides who gained access","to make every figure larger","to remove limitations"]},{"id":"en-c1-22-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"finding → interpretation → limitation → recommendation","options":["Attendance increased during the trial, mainly among students already living near the school.","The timetable changed at the same time as a promotional campaign.","A report attributing the increase entirely to the timetable would ignore a possible confound.","The writer separates the observed pattern from its interpretation and recommends another trial that records how participants heard about the sessions.","She also disaggregates the total by the groups relevant to the access objective.","The limitation appears beside the finding because it changes what can be inferred, rather than as a minor footnote.","Analytical reporting is useful when it helps decision makers see both a pattern and the questions that pattern leaves unanswered."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is confound. Attendance increased during the trial, mainly among students already living near the school. The timetable changed at the same time as a promotional campaign. Speaker two: My main point is provisional. The recommendation remains provisional until competing explanations are tested. Attendance increased during the trial, mainly among students already living near the school. The timetable changed at the same time as a promotional campaign. A report attributing the increase entirely to the timetable would ignore a possible confound. The writer separates the observed pattern from its interpretation and recommends another trial that records how participants heard about the sessions. She also disaggregates the total by the groups relevant to the access objective. The limitation appears beside the finding because it changes what can be inferred, rather than as a minor footnote. Analytical reporting is useful when it helps decision makers see both a pattern and the questions that pattern leaves unanswered.","audio":"/english-course/v7.23/en-c1-22.mp3","synthetic":true,"questions":[{"id":"en-c1-22-listening0","type":"choice","skill":"listening","prompt":"Confound nima?","answers":["promotion changed at the same time"],"explanation":"Ikki o‘zgarish bir vaqtda.","hint":"finding → interpretation → limitation → recommendation","options":["promotion changed at the same time","attendance was never counted","all distant students came"]},{"id":"en-c1-22-listening1","type":"choice","skill":"listening","prompt":"Disaggregate nega?","answers":["total hides who gained access"],"explanation":"Group-specific aim.","hint":"finding → interpretation → limitation → recommendation","options":["total hides who gained access","to make every figure larger","to remove limitations"]},{"id":"en-c1-22-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["confound","provisional"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"finding → interpretation → limitation → recommendation","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-22-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The report cannot separate that effect from promotion."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"finding → interpretation → limitation → recommendation","audio":"/english-course/v7.23/en-c1-22-dictation.mp3","transcript":"The report cannot separate that effect from promotion."}]},"writing":{"task":"Analytical report: disaggregated finding, two interpretations, limitation va testable recommendation.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Attendance increased during the trial, but the increase was concentrated among students living near the school. The timetable revision and promotional campaign occurred together, so the report cannot separate their effects. I recommend a second trial that records how participants heard about the sessions and compares participation by the groups relevant to the access objective. The recommendation is provisional. Presenting the limitation beside the finding makes clear why the total is encouraging but insufficient to establish that the timetable alone improved equitable access.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Attendance increased during the trial.","The increase was concentrated in one group.","The pattern may reflect the revised timetable."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Analytical report: disaggregated finding, two interpretations, limitation va testable recommendation. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Analytical report: disaggregated finding, two interpretations, limitation va testable recommendation.","exit":[[{"id":"en-c1-22-exit0","type":"grammarFill","skill":"grammar","prompt":"The increase was ___ in one group. (concentrate)","answers":["concentrated"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation"},{"id":"en-c1-22-exit1","type":"grammarFill","skill":"grammar","prompt":"The pattern may ___ the timetable. (reflect)","answers":["reflect"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation"},{"id":"en-c1-22-exit2","type":"grammarFill","skill":"grammar","prompt":"The report cannot ___ the effects. (separate)","answers":["separate"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation"},{"id":"en-c1-22-exit3","type":"choice","skill":"grammar","prompt":"Confound nima?","answers":["promotion changed at the same time"],"explanation":"Ikki o‘zgarish bir vaqtda.","hint":"finding → interpretation → limitation → recommendation","options":["promotion changed at the same time","attendance was never counted","all distant students came"]},{"id":"en-c1-22-exit4","type":"choice","skill":"grammar","prompt":"Disaggregate nega?","answers":["total hides who gained access"],"explanation":"Group-specific aim.","hint":"finding → interpretation → limitation → recommendation","options":["total hides who gained access","to make every figure larger","to remove limitations"]}],[{"id":"en-c1-22-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The increase was concentrated in one group."],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation","tokens":["The","increase","was","concentrated","in","one","group."]},{"id":"en-c1-22-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The pattern may ___ the timetable. (reflect)","answers":["reflect"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation"},{"id":"en-c1-22-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The report cannot separate that effect from promotion."],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation","tokens":["The","report","cannot","separate","that","effect","from","promotion."]},{"id":"en-c1-22-exit-b3","type":"choice","skill":"grammar","prompt":"Confound nima?","answers":["promotion changed at the same time"],"explanation":"Ikki o‘zgarish bir vaqtda.","hint":"finding → interpretation → limitation → recommendation","options":["promotion changed at the same time","attendance was never counted","all distant students came"]},{"id":"en-c1-22-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The recommendation is provisional rather than permanent."],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation","tokens":["The","recommendation","is","provisional","rather","than","permanent."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-22","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-23','en-c1-23',null,5,23,'published',1,'{"id":"en-c1-23","baseId":"en-c1-23","revision":1,"level":"C1","levelIndex":5,"order":23,"title":"Seminar, debat va muzokara","objective":"Boshqa fikrni xolis qayta aytib, shartli kelishuvga olib kelasiz.","context":"Seminar, debat va muzokara","prerequisites":["en-c1-22"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Avval opponentning maqsad va dalilini tekshirib paraphrase qiling.","Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda?","Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi."],"pattern":"If I understand you correctly … / Could we agree provided that …?","examples":["If I understand you correctly, staffing is your priority.","That is a fair concern, although access also matters.","Could we agree provided that supervision is confirmed?","Let me distinguish the cost from the scheduling issue.","What evidence would change your position?","Our agreement is conditional on the review."],"vocabulary":[{"id":"en-c1-23-v0","term":"concession","meaning":"kelishishga yaqin qism","ipa":"/kənˈseʃən/","collocation":"offer a concession","example":"offer a concession"},{"id":"en-c1-23-v1","term":"interest","meaning":"asosiy ehtiyoj","ipa":"/ˈɪntrəst/","collocation":"identify shared interests","example":"These interests are not identical, but they are not automatically incompatible."},{"id":"en-c1-23-v2","term":"impasse","meaning":"kelishuvsiz holat","ipa":"/ˈɪmpɑːs/","collocation":"resolve an impasse","example":"resolve an impasse"},{"id":"en-c1-23-v3","term":"conditional","meaning":"shartli","ipa":"/kənˈdɪʃənəl/","collocation":"a conditional agreement","example":"Our agreement is conditional on the review."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["If I understand you correctly … / Could we agree provided that …?","If I understand you correctly, staffing is your priority.","That is a fair concern, although access also matters."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Positions appear incompatible.","Underlying interests concern staffing and access.","Verify a workable conditional agreement."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Let me distinguish the cost from the scheduling issue.","audio":"/english-course/v7.23/en-c1-23-dictation.mp3"},"exercises":[{"id":"en-c1-23-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: If I understand you ___, staffing matters.","answers":["correctly"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["correctly","correct","correctness"]},{"id":"en-c1-23-gap","type":"grammarFill","skill":"grammar","prompt":"If I understand you ___, staffing matters.","answers":["correctly"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?"},{"id":"en-c1-23-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["If I understand you correctly, staffing is your priority."],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?","tokens":["If","I","understand","you","correctly,","staffing","is","your","priority."]},{"id":"en-c1-23-fix","type":"correction","skill":"grammar","prompt":"A polite nod proves unconditional agreement.","answers":["A polite nod should be checked before being recorded as unconditional agreement."],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?"},{"id":"en-c1-23-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["kelishishga yaqin qism","asosiy ehtiyoj","kelishuvsiz holat","shartli"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"If I understand you correctly … / Could we agree provided that …?","left":["concession","interest","impasse","conditional"],"options":["kelishishga yaqin qism","asosiy ehtiyoj","kelishuvsiz holat","shartli"]},{"id":"en-c1-23-transform","type":"transformation","skill":"grammar","prompt":"Clarification so‘rang: Your priority seems to be staffing.","answers":["If I understand you correctly, staffing is your priority."],"hint":"If I understand you correctly … / Could we agree provided that …?","explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling."},{"id":"en-c1-23-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Positions appear incompatible.","Underlying interests concern staffing and access.","Verify a workable conditional agreement."],"answers":["Positions appear incompatible.\nUnderlying interests concern staffing and access.\nVerify a workable conditional agreement."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Two committee members disagree about the trial. One demands a fixed day, while the other insists on flexibility. The discussion becomes more productive when a student asks what each position protects. The fixed-day supporter needs reliable staffing; the flexibility supporter wants distant students to participate. These interests are not identical, but they are not automatically incompatible. The group considers alternating only between two days with confirmed supervision. Before accepting, one member paraphrases the proposal and checks the review condition. This prevents a polite nod from being recorded as unconditional agreement. A successful negotiation need not eliminate every difference. It should identify a workable next step, the conditions of consent, and the evidence that will guide reconsideration.","sentences":["Two committee members disagree about the trial.","One demands a fixed day, while the other insists on flexibility.","The discussion becomes more productive when a student asks what each position protects.","The fixed-day supporter needs reliable staffing; the flexibility supporter wants distant students to participate.","These interests are not identical, but they are not automatically incompatible.","The group considers alternating only between two days with confirmed supervision.","Before accepting, one member paraphrases the proposal and checks the review condition.","This prevents a polite nod from being recorded as unconditional agreement.","A successful negotiation need not eliminate every difference.","It should identify a workable next step, the conditions of consent, and the evidence that will guide reconsideration."],"questions":[{"id":"en-c1-23-reading0","type":"choice","skill":"reading","prompt":"Pozitsiya ortidagi birinchi ehtiyoj?","answers":["reliable staffing"],"explanation":"Fixed day staff reliability.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["reliable staffing","dislike of distant students","no trial ever"]},{"id":"en-c1-23-reading1","type":"choice","skill":"reading","prompt":"Paraphrase nega kerak?","answers":["to verify conditional agreement"],"explanation":"Shartli assentni tekshirish.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["to verify conditional agreement","to silence disagreement","to prove permanent consent"]},{"id":"en-c1-23-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["Two committee members disagree about the trial.","One demands a fixed day, while the other insists on flexibility.","The discussion becomes more productive when a student asks what each position protects.","The fixed-day supporter needs reliable staffing; the flexibility supporter wants distant students to participate.","These interests are not identical, but they are not automatically incompatible.","The group considers alternating only between two days with confirmed supervision.","Before accepting, one member paraphrases the proposal and checks the review condition.","This prevents a polite nod from being recorded as unconditional agreement.","A successful negotiation need not eliminate every difference.","It should identify a workable next step, the conditions of consent, and the evidence that will guide reconsideration."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is interest. Two committee members disagree about the trial. One demands a fixed day, while the other insists on flexibility. Speaker two: My main point is conditional. Check the conditions before recording agreement. Two committee members disagree about the trial. One demands a fixed day, while the other insists on flexibility. The discussion becomes more productive when a student asks what each position protects. The fixed-day supporter needs reliable staffing; the flexibility supporter wants distant students to participate. These interests are not identical, but they are not automatically incompatible. The group considers alternating only between two days with confirmed supervision. Before accepting, one member paraphrases the proposal and checks the review condition. This prevents a polite nod from being recorded as unconditional agreement. A successful negotiation need not eliminate every difference. It should identify a workable next step, the conditions of consent, and the evidence that will guide reconsideration.","audio":"/english-course/v7.23/en-c1-23.mp3","synthetic":true,"questions":[{"id":"en-c1-23-listening0","type":"choice","skill":"listening","prompt":"Pozitsiya ortidagi birinchi ehtiyoj?","answers":["reliable staffing"],"explanation":"Fixed day staff reliability.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["reliable staffing","dislike of distant students","no trial ever"]},{"id":"en-c1-23-listening1","type":"choice","skill":"listening","prompt":"Paraphrase nega kerak?","answers":["to verify conditional agreement"],"explanation":"Shartli assentni tekshirish.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["to verify conditional agreement","to silence disagreement","to prove permanent consent"]},{"id":"en-c1-23-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["interest","conditional"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"If I understand you correctly … / Could we agree provided that …?","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-23-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Let me distinguish the cost from the scheduling issue."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"If I understand you correctly … / Could we agree provided that …?","audio":"/english-course/v7.23/en-c1-23-dictation.mp3","transcript":"Let me distinguish the cost from the scheduling issue."}]},"writing":{"task":"Role-play muzokara: ikki conflicting interest, concession, conditional agreement va review.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The fixed-day position protects reliable staffing, while the flexible position protects access for distant students. I suggest alternating between two days only when supervision is confirmed. Before recording agreement, we should ask each member to state whether those conditions match their understanding. The trial would be reviewed using participation evidence after two weeks. This is a conditional next step rather than a permanent settlement. Negotiation becomes more productive when participants identify the needs behind their positions and verify consent instead of interpreting politeness as agreement.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["If I understand you correctly, staffing is your priority.","That is a fair concern, although access also matters.","Could we agree provided that supervision is confirmed?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Role-play muzokara: ikki conflicting interest, concession, conditional agreement va review. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Role-play muzokara: ikki conflicting interest, concession, conditional agreement va review.","exit":[[{"id":"en-c1-23-exit0","type":"grammarFill","skill":"grammar","prompt":"If I understand you ___, staffing matters.","answers":["correctly"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?"},{"id":"en-c1-23-exit1","type":"grammarFill","skill":"grammar","prompt":"Could we agree ___ that supervision is confirmed?","answers":["provided"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?"},{"id":"en-c1-23-exit2","type":"grammarFill","skill":"grammar","prompt":"Our agreement is conditional ___ review.","answers":["on"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?"},{"id":"en-c1-23-exit3","type":"choice","skill":"grammar","prompt":"Pozitsiya ortidagi birinchi ehtiyoj?","answers":["reliable staffing"],"explanation":"Fixed day staff reliability.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["reliable staffing","dislike of distant students","no trial ever"]},{"id":"en-c1-23-exit4","type":"choice","skill":"grammar","prompt":"Paraphrase nega kerak?","answers":["to verify conditional agreement"],"explanation":"Shartli assentni tekshirish.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["to verify conditional agreement","to silence disagreement","to prove permanent consent"]}],[{"id":"en-c1-23-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["That is a fair concern, although access also matters."],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?","tokens":["That","is","a","fair","concern,","although","access","also","matters."]},{"id":"en-c1-23-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Could we agree ___ that supervision is confirmed?","answers":["provided"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?"},{"id":"en-c1-23-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Let me distinguish the cost from the scheduling issue."],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?","tokens":["Let","me","distinguish","the","cost","from","the","scheduling","issue."]},{"id":"en-c1-23-exit-b3","type":"choice","skill":"grammar","prompt":"Pozitsiya ortidagi birinchi ehtiyoj?","answers":["reliable staffing"],"explanation":"Fixed day staff reliability.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["reliable staffing","dislike of distant students","no trial ever"]},{"id":"en-c1-23-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Our agreement is conditional on the review."],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?","tokens":["Our","agreement","is","conditional","on","the","review."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-23","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-24','en-c1-24',null,5,24,'published',1,'{"id":"en-c1-24","baseId":"en-c1-24","revision":1,"level":"C1","levelIndex":5,"order":24,"title":"C1 loyiha: manbadan taqdimotgacha","objective":"Talabchan materialni synthesis, proposal va spontan savol-javobga aylantirasiz.","context":"C1 loyiha: manbadan taqdimotgacha","prerequisites":["en-c1-23"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Synthesisda har manba claim, method va limitationini saqlang.","Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering.","C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak."],"pattern":"analyse → synthesise → propose → defend → revise","examples":["The sources converge on the importance of access.","They diverge on how demand was measured.","The proposal remains conditional on staffing.","A plausible objection concerns selection bias.","In response, I would broaden the sample.","The final recommendation should reflect that revision."],"vocabulary":[{"id":"en-c1-24-v0","term":"convergence","meaning":"mos dalillar","ipa":"/kənˈvɜːdʒəns/","collocation":"identify convergence","example":"identify convergence"},{"id":"en-c1-24-v1","term":"selection bias","meaning":"tanlov og‘ishi","ipa":"/sɪˈlekʃən baɪəs/","collocation":"address selection bias","example":"A plausible objection concerns selection bias."},{"id":"en-c1-24-v2","term":"defensible","meaning":"asoslanadigan","ipa":"/dɪˈfensəbəl/","collocation":"a defensible recommendation","example":"A defensible decision links evidence, conditions, and willingness to reconsider rather than presenting confidence as proof."},{"id":"en-c1-24-v3","term":"revision","meaning":"qayta ishlash","ipa":"/rɪˈvɪʒən/","collocation":"evidence-based revision","example":"The final recommendation should reflect that revision."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["analyse → synthesise → propose → defend → revise","The sources converge on the importance of access.","They diverge on how demand was measured."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The sources measure different aspects of access.","A trial can test a limited combined response.","Review evidence and revise when the conditions fail."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"A plausible objection concerns selection bias.","audio":"/english-course/v7.23/en-c1-24-dictation.mp3"},"exercises":[{"id":"en-c1-24-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The sources ___ on the importance of access. (converge)","answers":["converge"],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise","options":["converge","converges","converging"]},{"id":"en-c1-24-gap","type":"grammarFill","skill":"grammar","prompt":"The sources ___ on the importance of access. (converge)","answers":["converge"],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise"},{"id":"en-c1-24-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The sources converge on the importance of access."],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise","tokens":["The","sources","converge","on","the","importance","of","access."]},{"id":"en-c1-24-fix","type":"correction","skill":"grammar","prompt":"A confident presentation proves that every source is reliable.","answers":["A confident presentation does not establish that every source is reliable."],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise"},{"id":"en-c1-24-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["mos dalillar","tanlov og‘ishi","asoslanadigan","qayta ishlash"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"analyse → synthesise → propose → defend → revise","left":["convergence","selection bias","defensible","revision"],"options":["mos dalillar","tanlov og‘ishi","asoslanadigan","qayta ishlash"]},{"id":"en-c1-24-transform","type":"transformation","skill":"grammar","prompt":"Conditional proposal: We can trial both days if staffing is confirmed.","answers":["We can trial both days provided that staffing is confirmed."],"hint":"analyse → synthesise → propose → defend → revise","explanation":"Synthesisda har manba claim, method va limitationini saqlang."},{"id":"en-c1-24-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The sources measure different aspects of access.","A trial can test a limited combined response.","Review evidence and revise when the conditions fail."],"answers":["The sources measure different aspects of access.\nA trial can test a limited combined response.\nReview evidence and revise when the conditions fail."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-24-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["convergence","selection bias","defensible","revision"],"options":["identify convergence","address selection bias","a defensible recommendation","evidence-based revision"],"answers":["identify convergence","address selection bias","a defensible recommendation","evidence-based revision"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."},{"id":"en-c1-24-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["The sources converge on the importance of access."],"tokens":["The","sources","converge","on","the","importance","of","access."],"hint":"analyse → synthesise → propose → defend → revise","explanation":"Synthesisda har manba claim, method va limitationini saqlang."},{"id":"en-c1-24-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Proposal: ehtiyoj, resurs va baholash: Til vositasini tanlang: Success would be assessed ___ criteria.","answers":["against"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation","options":["against","onto","at"],"recap":true,"sourceLesson":"Proposal: ehtiyoj, resurs va baholash"},{"id":"en-c1-24-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Analytical report: pattern va limitation: Til vositasini tanlang: The increase was ___ in one group. (concentrate)","answers":["concentrated"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation","options":["concentrated","concentrating","concentrate"],"recap":true,"sourceLesson":"Analytical report: pattern va limitation"},{"id":"en-c1-24-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Seminar, debat va muzokara: Til vositasini tanlang: If I understand you ___, staffing matters.","answers":["correctly"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["correctly","correct","correctness"],"recap":true,"sourceLesson":"Seminar, debat va muzokara"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Source A reports a survey of sixty students, most of whom prefer a fixed afternoon. Respondents completed it voluntarily through a link shared in the school group. The report treats preference as evidence of demand, but it does not show whether non-respondents face different constraints. Source B presents six interviews with students living far from the school. They describe transport difficulties and favour rotating days. These interviews explain a barrier but cannot estimate how common it is across the school. Source C records staffing availability. Two afternoons have reliable supervision, although one depends on a teacher who may leave next term. Taken together, the sources support a bounded trial on those two days, not a permanent claim that every group will benefit. The evaluation should record participation by relevant groups, distinguish attendance from active engagement, and ask how students heard about the sessions. A presenter must also explain what evidence would change the recommendation. If distant students still cannot attend, rotation alone may not address the barrier. If staffing becomes unreliable, the proposal needs revision even if demand is strong. A defensible decision links evidence, conditions, and willingness to reconsider rather than presenting confidence as proof.","sentences":["Source A reports a survey of sixty students, most of whom prefer a fixed afternoon.","Respondents completed it voluntarily through a link shared in the school group.","The report treats preference as evidence of demand, but it does not show whether non-respondents face different constraints.","Source B presents six interviews with students living far from the school.","They describe transport difficulties and favour rotating days.","These interviews explain a barrier but cannot estimate how common it is across the school.","Source C records staffing availability.","Two afternoons have reliable supervision, although one depends on a teacher who may leave next term.","Taken together, the sources support a bounded trial on those two days, not a permanent claim that every group will benefit.","The evaluation should record participation by relevant groups, distinguish attendance from active engagement, and ask how students heard about the sessions.","A presenter must also explain what evidence would change the recommendation.","If distant students still cannot attend, rotation alone may not address the barrier.","If staffing becomes unreliable, the proposal needs revision even if demand is strong.","A defensible decision links evidence, conditions, and willingness to reconsider rather than presenting confidence as proof."],"questions":[{"id":"en-c1-24-reading0","type":"choice","skill":"reading","prompt":"B intervyularining cheklovi?","answers":["they cannot estimate school-wide prevalence"],"explanation":"Olti kishidan frequency umumlashmaydi.","hint":"analyse → synthesise → propose → defend → revise","options":["they cannot estimate school-wide prevalence","they contain no barriers","they have sixty respondents"]},{"id":"en-c1-24-reading1","type":"choice","skill":"reading","prompt":"Final tavsiya qanday?","answers":["a bounded trial with conditions and review"],"explanation":"Har manba limitini saqlaydi.","hint":"analyse → synthesise → propose → defend → revise","options":["a bounded trial with conditions and review","a permanent guarantee","a decision based only on confidence"]},{"id":"en-c1-24-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"analyse → synthesise → propose → defend → revise","options":["Source A reports a survey of sixty students, most of whom prefer a fixed afternoon.","Respondents completed it voluntarily through a link shared in the school group.","The report treats preference as evidence of demand, but it does not show whether non-respondents face different constraints.","Source B presents six interviews with students living far from the school.","They describe transport difficulties and favour rotating days.","These interviews explain a barrier but cannot estimate how common it is across the school.","Source C records staffing availability.","Two afternoons have reliable supervision, although one depends on a teacher who may leave next term.","Taken together, the sources support a bounded trial on those two days, not a permanent claim that every group will benefit.","The evaluation should record participation by relevant groups, distinguish attendance from active engagement, and ask how students heard about the sessions.","A presenter must also explain what evidence would change the recommendation.","If distant students still cannot attend, rotation alone may not address the barrier.","If staffing becomes unreliable, the proposal needs revision even if demand is strong.","A defensible decision links evidence, conditions, and willingness to reconsider rather than presenting confidence as proof."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is selection bias. Source A reports a survey of sixty students, most of whom prefer a fixed afternoon. Respondents completed it voluntarily through a link shared in the school group. Speaker two: My main point is revision. A defensible recommendation identifies what evidence would require revision. Source A reports a survey of sixty students, most of whom prefer a fixed afternoon. Respondents completed it voluntarily through a link shared in the school group. The report treats preference as evidence of demand, but it does not show whether non-respondents face different constraints. Source B presents six interviews with students living far from the school. They describe transport difficulties and favour rotating days. These interviews explain a barrier but cannot estimate how common it is across the school. Source C records staffing availability. Two afternoons have reliable supervision, although one depends on a teacher who may leave next term. Taken together, the sources support a bounded trial on those two days, not a permanent claim that every group will benefit. The evaluation should record participation by relevant groups, distinguish attendance from active engagement, and ask how students heard about the sessions. A presenter must also explain what evidence would change the recommendation. If distant students still cannot attend, rotation alone may not address the barrier. If staffing becomes unreliable, the proposal needs revision even if demand is strong. A defensible decision links evidence, conditions, and willingness to reconsider rather than presenting confidence as proof.","audio":"/english-course/v7.23/en-c1-24.mp3","synthetic":true,"questions":[{"id":"en-c1-24-listening0","type":"choice","skill":"listening","prompt":"B intervyularining cheklovi?","answers":["they cannot estimate school-wide prevalence"],"explanation":"Olti kishidan frequency umumlashmaydi.","hint":"analyse → synthesise → propose → defend → revise","options":["they cannot estimate school-wide prevalence","they contain no barriers","they have sixty respondents"]},{"id":"en-c1-24-listening1","type":"choice","skill":"listening","prompt":"Final tavsiya qanday?","answers":["a bounded trial with conditions and review"],"explanation":"Har manba limitini saqlaydi.","hint":"analyse → synthesise → propose → defend → revise","options":["a bounded trial with conditions and review","a permanent guarantee","a decision based only on confidence"]},{"id":"en-c1-24-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["selection bias","revision"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"analyse → synthesise → propose → defend → revise","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-24-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["A plausible objection concerns selection bias."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"analyse → synthesise → propose → defend → revise","audio":"/english-course/v7.23/en-c1-24-dictation.mp3","transcript":"A plausible objection concerns selection bias."}]},"writing":{"task":"C1 yakuniy loyiha: uch manba synthesisidan 180–250 so‘zli proposal yozing. 2–3 daqiqali taqdimot qiling va selection bias hamda staffing haqida spontan savolga javob bering.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":180,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"We recommend a bounded trial alternating between the two afternoons with confirmed supervision. The sources converge on the importance of access, but they measure different things. The voluntary survey records preference among respondents, while six interviews explain transport constraints for a particular group. Neither establishes how common every barrier is across the school. Staffing records identify feasible days, although one arrangement may change next term.\n\nThe trial should therefore collect participation data by relevant groups rather than rely on a total alone. It should also ask how students heard about the sessions, since promotion could affect attendance independently of the timetable. Active engagement should be assessed separately from presence. The organiser would coordinate staffing and publish a review date before the trial begins.\n\nA reasonable objection concerns selection bias in the survey. We would address it by inviting responses through more than one route and checking which groups remain underrepresented. Should supervision become unreliable, the original timetable would remain. If distant students still cannot attend, rotation alone may be insufficient. The recommendation is defensible because it names its evidence, conditions, and grounds for revision rather than claiming a permanent solution.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The sources converge on the importance of access.","They diverge on how demand was measured.","The proposal remains conditional on staffing."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Uch manbani qiyoslang, proposalni 2–3 daqiqada himoya qiling, keyin sherikning kutilmagan savoliga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"C1 yakuniy loyiha: uch manba synthesisidan 180–250 so‘zli proposal yozing. 2–3 daqiqali taqdimot qiling va selection bias hamda staffing haqida spontan savolga javob bering.","exit":[[{"id":"en-c1-24-exit0","type":"grammarFill","skill":"grammar","prompt":"The sources ___ on the importance of access. (converge)","answers":["converge"],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise"},{"id":"en-c1-24-exit1","type":"grammarFill","skill":"grammar","prompt":"The proposal is conditional ___ staffing.","answers":["on"],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise"},{"id":"en-c1-24-exit2","type":"grammarFill","skill":"grammar","prompt":"The recommendation should ___ the revision. (reflect)","answers":["reflect"],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise"},{"id":"en-c1-24-exit3","type":"choice","skill":"grammar","prompt":"B intervyularining cheklovi?","answers":["they cannot estimate school-wide prevalence"],"explanation":"Olti kishidan frequency umumlashmaydi.","hint":"analyse → synthesise → propose → defend → revise","options":["they cannot estimate school-wide prevalence","they contain no barriers","they have sixty respondents"]},{"id":"en-c1-24-exit4","type":"choice","skill":"grammar","prompt":"Final tavsiya qanday?","answers":["a bounded trial with conditions and review"],"explanation":"Har manba limitini saqlaydi.","hint":"analyse → synthesise → propose → defend → revise","options":["a bounded trial with conditions and review","a permanent guarantee","a decision based only on confidence"]}],[{"id":"en-c1-24-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They diverge on how demand was measured."],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise","tokens":["They","diverge","on","how","demand","was","measured."]},{"id":"en-c1-24-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The proposal is conditional ___ staffing.","answers":["on"],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise"},{"id":"en-c1-24-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["A plausible objection concerns selection bias."],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise","tokens":["A","plausible","objection","concerns","selection","bias."]},{"id":"en-c1-24-exit-b3","type":"choice","skill":"grammar","prompt":"B intervyularining cheklovi?","answers":["they cannot estimate school-wide prevalence"],"explanation":"Olti kishidan frequency umumlashmaydi.","hint":"analyse → synthesise → propose → defend → revise","options":["they cannot estimate school-wide prevalence","they contain no barriers","they have sixty respondents"]},{"id":"en-c1-24-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The final recommendation should reflect that revision."],"explanation":"Synthesisda har manba claim, method va limitationini saqlang. Proposal xulosa bilan actionni bog‘lasin; speakingda e’tirozga yangi, relevant javob bering. C1 ichki loyiha natijasi rasmiy sertifikat emas; to‘rt ko‘nikma uchun rubrika dalili kerak.","hint":"analyse → synthesise → propose → defend → revise","tokens":["The","final","recommendation","should","reflect","that","revision."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-understand","name":"Cambridge English — Can you understand? (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l069-can-you-understand","task":"Pozitsiya va yashirin ma’noga dalil bo‘lgan iborani qayd eting.","lesson":"en-c1-24","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":true,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-c1-24-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Proposal: ehtiyoj, resurs va baholash: Til vositasini tanlang: Success would be assessed ___ criteria.","answers":["against"],"explanation":"Proposal ehtiyoj, taklif, implementation, resurs, risk va evaluationni bog‘laydi. Success criterion faqat ish bajarilishi emas, maqsadga mos natija. Contingency va mas’ul shaxs ochiq; o‘lchanmagan natijani kafolatlamang.","hint":"need → action → resources → risk → evaluation","options":["against","onto","at"],"recap":true,"sourceLesson":"Proposal: ehtiyoj, resurs va baholash"},{"id":"en-c1-24-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Analytical report: pattern va limitation: Til vositasini tanlang: The increase was ___ in one group. (concentrate)","answers":["concentrated"],"explanation":"Description data nimani ko‘rsatdi; interpretation nega bo‘lishi mumkin; recommendation nima qilish. Patternni individual exception bilan inkor yoki universal rule bilan kuchaytirmang. Limitationni appendixga yashirmang: xulosa doirasiga ta’sir etsa yonida yozing.","hint":"finding → interpretation → limitation → recommendation","options":["concentrated","concentrating","concentrate"],"recap":true,"sourceLesson":"Analytical report: pattern va limitation"},{"id":"en-c1-24-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Seminar, debat va muzokara: Til vositasini tanlang: If I understand you ___, staffing matters.","answers":["correctly"],"explanation":"Avval opponentning maqsad va dalilini tekshirib paraphrase qiling. Negotiation pozitsiyadan ehtiyojga o‘tadi: qaysi constraint va priority ortda? Spontan clarification, concession va summary qaror shartlarini ko‘rsatadi.","hint":"If I understand you correctly … / Could we agree provided that …?","options":["correctly","correct","correctness"],"recap":true,"sourceLesson":"Seminar, debat va muzokara"}]}'::jsonb) on conflict(id,revision) do nothing;
